#!/bin/bash
set -uo pipefail
QE="searchlib_array_bool_test_app searchlib_blueprint_test_app searchlib_dot_product_test_app searchlib_equiv_test_app searchlib_exact_nearest_neighbor_test_app searchlib_fake_index_test_app searchlib_fake_searchable_test_app searchlib_filter_search_test_app searchlib_getnodeweight_test_app searchlib_intermediate_blueprints_test_app searchlib_leaf_blueprints_test_app searchlib_matching_elements_search_test_app searchlib_monitoring_search_iterator_test_app searchlib_multibitvectoriterator_bench_app searchlib_multibitvectoriterator_test_app searchlib_or_speed_test_app searchlib_parallel_weak_and_bench_app searchlib_parallel_weak_and_test_app searchlib_predicate_blueprint_test_app searchlib_predicate_search_test_app searchlib_queryeval_flow_test_app searchlib_queryeval_global_filter_test_app searchlib_queryeval_lazy_filter_test_app searchlib_queryeval_profiled_iterator_test_app searchlib_queryeval_test_app searchlib_same_element_test_app searchlib_simple_phrase_test_app searchlib_sourceblender_test_app searchlib_sparse_vector_benchmark_test_app searchlib_termwise_eval_test_app searchlib_weak_and_bench_app searchlib_weak_and_heap_test_app searchlib_weak_and_scorers_test_app searchlib_weak_and_test_app searchlib_weak_and_test_expensive_app searchlib_weighted_set_term_test_app searchlib_wrappers_test_app"
SC="searchcore_query_test_app searchcore_querynodes_test_app searchcore_matching_test_app searchcore_indexmanager_test_app searchcore_fusionrunner_test_app searchcore_indexcollection_test_app"
/work/mk.sh make-tests $QE $SC || exit 1
docker exec vbuild bash -lc "cd /work/vespa/build/searchlib/src/tests/queryeval && ctest -j 32 --output-on-failure 2>&1 | tail -15" > /work/results/ctest-queryeval-v2.txt
docker exec vbuild bash -lc "cd /work/vespa/build/searchcore/src/tests/proton && ctest -j 16 -R 'searchcore_(query|querynodes|matching|indexmanager|fusionrunner|indexcollection)_test_app' --output-on-failure 2>&1 | tail -15" > /work/results/ctest-searchcore-v2.txt
tail -4 /work/results/ctest-queryeval-v2.txt /work/results/ctest-searchcore-v2.txt
